<script setup>
import { Head, useForm, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import HrmsLayout from '@/Layouts/HrmsLayout.vue';
const props = defineProps({ employees:Array, departments:Array, canManage:Boolean });
const page = usePage();
const ownProfile = computed(() => props.employees.find(e => e.id === page.props.auth.employee?.id));
const show = ref(false), editing = ref(null);
const blank = () => ({ employee_number:'', first_name:'', last_name:'', department_id:'', job_title:'', hire_date:'', contract_type:'full_time', employment_status:'active', phone:'', personal_email:'', account_email:'', account_password:'', salary_basis:'monthly', base_rate:'', currency:'SAR', effective_from:'' });
const form = useForm(blank());
const openNew = () => { editing.value=null; form.defaults(blank()); form.reset(); show.value=true; };
const edit = item => { editing.value=item; form.defaults({...blank(), employee_number:item.employee_number, first_name:item.first_name, last_name:item.last_name, department_id:item.department_id, job_title:item.job_title, hire_date:item.hire_date?.slice(0,10), contract_type:item.contract_type, employment_status:item.employment_status, phone:item.phone || '', personal_email:item.personal_email || ''}); form.reset(); show.value=true; window.scrollTo({top:0,behavior:'smooth'}); };
const save = () => { const options={onSuccess:()=>{show.value=false;editing.value=null;form.reset();}}; editing.value ? form.put(route('employees.update',editing.value.id),options) : form.post(route('employees.store'),options); };
const archive = item => { if(confirm(`أرشفة ملف ${item.first_name} ${item.last_name}؟`)) form.delete(route('employees.destroy',item.id)); };
</script>
<template>
    <Head title="الموظفون" />
    <HrmsLayout title="دليل الموظفين" subtitle="ملفات الفريق والبيانات الوظيفية في مكان واحد.">
        <template #actions><button v-if="canManage" class="btn-primary" @click="openNew">إضافة موظف</button></template>
        <section v-if="ownProfile && !canManage" class="panel mb-6 p-5 sm:p-6"><h2 class="text-lg font-bold text-[#1F3A5F]">ملفي الوظيفي</h2><div class="mt-4 grid gap-4 text-sm sm:grid-cols-2 lg:grid-cols-3"><div><p class="text-slate-500">الاسم</p><p class="mt-1 font-semibold">{{ ownProfile.first_name }} {{ ownProfile.last_name }}</p></div><div><p class="text-slate-500">رقم الموظف</p><p class="mt-1 font-semibold">{{ ownProfile.employee_number }}</p></div><div><p class="text-slate-500">القسم</p><p class="mt-1 font-semibold">{{ ownProfile.department?.name }}</p></div><div><p class="text-slate-500">المسمى الوظيفي</p><p class="mt-1 font-semibold">{{ ownProfile.job_title }}</p></div><div><p class="text-slate-500">تاريخ التعيين</p><p class="mt-1 font-semibold">{{ ownProfile.hire_date?.slice(0,10) }}</p></div><div><p class="text-slate-500">نوع العقد</p><p class="mt-1 font-semibold">{{ {full_time:'دوام كامل',part_time:'دوام جزئي',fixed_term:'عقد محدد',contractor:'متعاقد'}[ownProfile.contract_type] || ownProfile.contract_type }}</p></div><div><p class="text-slate-500">الهاتف</p><p class="mt-1 font-semibold">{{ ownProfile.phone || '—' }}</p></div><div><p class="text-slate-500">البريد الشخصي</p><p class="mt-1 font-semibold">{{ ownProfile.personal_email || '—' }}</p></div></div></section>
        <section v-if="show && canManage" class="panel mb-6 p-5 sm:p-6"><div class="mb-5 flex items-center justify-between"><h2 class="text-xl font-bold text-[#1F3A5F]">{{ editing ? 'تعديل بيانات الموظف' : 'إضافة موظف جديد' }}</h2><button class="text-sm text-slate-500 underline" @click="show=false">إغلاق</button></div>
            <form @submit.prevent="save" class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
                <div><label class="label" for="employee_number">رقم الموظف</label><input id="employee_number" v-model.trim="form.employee_number" class="field" required><p class="error" v-if="form.errors.employee_number">{{ form.errors.employee_number }}</p></div>
                <div><label class="label" for="first_name">الاسم الأول</label><input id="first_name" v-model.trim="form.first_name" class="field" required><p class="error" v-if="form.errors.first_name">{{ form.errors.first_name }}</p></div>
                <div><label class="label" for="last_name">اسم العائلة</label><input id="last_name" v-model.trim="form.last_name" class="field" required><p class="error" v-if="form.errors.last_name">{{ form.errors.last_name }}</p></div>
                <div><label class="label" for="department_id">القسم</label><select id="department_id" v-model="form.department_id" class="field" required><option value="">اختر القسم</option><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.name }}</option></select><p class="error" v-if="form.errors.department_id">{{ form.errors.department_id }}</p></div>
                <div><label class="label" for="job_title">المسمى الوظيفي</label><input id="job_title" v-model.trim="form.job_title" class="field" required><p class="error" v-if="form.errors.job_title">{{ form.errors.job_title }}</p></div>
                <div><label class="label" for="hire_date">تاريخ التعيين</label><input id="hire_date" type="date" v-model="form.hire_date" class="field" required><p class="error" v-if="form.errors.hire_date">{{ form.errors.hire_date }}</p></div>
                <div><label class="label" for="contract_type">نوع العقد</label><select id="contract_type" v-model="form.contract_type" class="field"><option value="full_time">دوام كامل</option><option value="part_time">دوام جزئي</option><option value="fixed_term">عقد محدد</option><option value="contractor">متعاقد</option></select></div>
                <div><label class="label" for="phone">الهاتف</label><input id="phone" v-model.trim="form.phone" class="field"></div>
                <div><label class="label" for="personal_email">البريد الشخصي</label><input id="personal_email" type="email" v-model.trim="form.personal_email" class="field"></div>
                <template v-if="!editing"><div><label class="label" for="account_email">بريد الدخول (اختياري)</label><input id="account_email" type="email" v-model.trim="form.account_email" class="field"><p class="error" v-if="form.errors.account_email">{{ form.errors.account_email }}</p></div><div><label class="label" for="account_password">كلمة المرور الأولية</label><input id="account_password" type="password" v-model="form.account_password" class="field"><p class="error" v-if="form.errors.account_password">{{ form.errors.account_password }}</p></div></template>
                <div><label class="label" for="salary_basis">أساس الراتب</label><select id="salary_basis" v-model="form.salary_basis" class="field"><option value="monthly">شهري</option><option value="daily">يومي</option><option value="hourly">بالساعة</option></select></div>
                <div><label class="label" for="base_rate">الراتب الأساسي {{ editing ? '(اتركه فارغًا دون تغيير)' : '' }}</label><input id="base_rate" type="number" min="0" step="0.01" v-model="form.base_rate" class="field"><p class="error" v-if="form.errors.base_rate">{{ form.errors.base_rate }}</p></div>
                <div><label class="label" for="currency">العملة</label><input id="currency" v-model.trim="form.currency" maxlength="3" class="field"></div>
                <div v-if="editing"><label class="label" for="effective_from">سريان تعديل الراتب</label><input id="effective_from" type="date" v-model="form.effective_from" class="field"></div>
                <div class="sm:col-span-2 xl:col-span-3 flex justify-end"><button class="btn-primary" :disabled="form.processing">{{ form.processing ? 'جارٍ الحفظ…' : 'حفظ الموظف' }}</button></div>
            </form>
        </section>
        <section class="panel overflow-hidden"><div class="border-b border-slate-100 px-5 py-4"><h2 class="text-lg font-bold text-[#1F3A5F]">سجل الموظفين <span class="text-sm font-normal text-slate-500">({{ employees.length }})</span></h2></div>
            <div class="overflow-x-auto"><table class="w-full min-w-[720px] text-right"><thead class="table-head"><tr><th class="px-4 py-3">الموظف</th><th class="px-4 py-3">القسم</th><th class="px-4 py-3">المسمى</th><th class="px-4 py-3">الحالة</th><th v-if="canManage" class="px-4 py-3">الراتب</th><th v-if="canManage" class="px-4 py-3">إجراءات</th></tr></thead><tbody><tr v-for="item in employees" :key="item.id" class="hover:bg-slate-50"><td class="table-cell"><div class="font-semibold text-slate-800">{{ item.first_name }} {{ item.last_name }}</div><div class="text-xs text-slate-500">{{ item.employee_number }}</div></td><td class="table-cell">{{ item.department?.name }}</td><td class="table-cell">{{ item.job_title }}</td><td class="table-cell">{{ item.employment_status==='active' ? 'نشط' : 'غير نشط' }}</td><td v-if="canManage" class="table-cell">{{ item.current_compensation?.base_rate || '—' }} {{ item.current_compensation?.currency || '' }}</td><td v-if="canManage" class="table-cell"><button class="font-semibold text-teal-700 hover:underline" @click="edit(item)">تعديل</button><button class="mr-3 text-red-700 hover:underline" @click="archive(item)">أرشفة</button></td></tr></tbody></table></div>
            <div v-if="!employees.length" class="p-8 text-sm text-slate-500">لا توجد ملفات موظفين ضمن نطاقك.</div>
        </section>
    </HrmsLayout>
</template>
